import { useEffect, useMemo, useState, type ElementType, type FormEvent, type ReactNode } from "react";
import { useLocation } from "wouter";
import { toast } from "sonner";
import { MapView } from "@/components/Map";
import { trpc } from "@/lib/trpc";
import { jsPDF } from "jspdf";
import { strToU8, zipSync } from "fflate";
import {
  ArrowDownUp, ArrowDownRight, ArrowUpRight, Bell, Bot, BriefcaseBusiness, Check, ChevronDown, ChevronRight,
  CircleHelp, Clock3, Copy, Database, ExternalLink, FileCode2, FileText, Filter, Gauge, KanbanSquare,
  KeyRound, LayoutDashboard, ListFilter, Moon, MoreHorizontal, PanelLeftClose, Plus, RefreshCw, Search,
  Send, Settings2, ShieldCheck, Sparkles, Sun, Target, TerminalSquare, Trash2, Users, X, Zap,
} from "lucide-react";

type Stage = "New" | "Contacted" | "Interested" | "Proposal" | "Won" | "Lost";
type Tone = "Formal" | "Casual" | "Short" | "Long" | "Hindi" | "Telugu";
type Lead = {
  id: string; business: string; niche: string; location: string; score: number; probability: number; stage: Stage;
  contact: string; phone?: string; lastTouch: string; value: number; initials: string; address?: string;
  website?: string; email?: string; placeId?: string; followUpDate?: string; replyStatus?: "waiting" | "replied" | "none";
  proposalSentAt?: string; outreach?: string; audit?: string; demoUrl?: string; proposal?: string; source?: string;
};

type Config = { ownerName: string; businessName: string; pan: string; upiId: string; netlifyToken: string; projectRate: string };
const stages: Stage[] = ["New", "Contacted", "Interested", "Proposal", "Won", "Lost"];
const STORAGE_KEY = "jarvis-leads";
const CONFIG_KEY = "jarvis-config";
const METRICS_KEY = "jarvis-metrics";
const navSections = [
  { label: "Workspace", items: [{ label: "Today", href: "/today", icon: Zap }, { label: "Dashboard", href: "/", icon: LayoutDashboard }, { label: "Find leads", href: "/find-leads", icon: Search }, { label: "Add leads", href: "/add-leads", icon: Plus }, { label: "Pipeline", href: "/pipeline", icon: KanbanSquare }] },
  { label: "Operations", items: [{ label: "AI tools", href: "/ai-tools", icon: Bot }, { label: "Revenue", href: "/revenue", icon: BriefcaseBusiness }, { label: "Logs", href: "/logs", icon: TerminalSquare }] },
  { label: "System", items: [{ label: "Settings", href: "/settings", icon: Settings2 }, { label: "Design system", href: "/design-system", icon: Sparkles }] },
];

function cn(...classes: Array<string | false | null | undefined>) { return classes.filter(Boolean).join(" "); }
function getSavedLeads(): Lead[] { if (typeof window === "undefined") return []; try { return JSON.parse(window.localStorage.getItem(STORAGE_KEY) ?? "[]") as Lead[]; } catch { return []; } }
function getConfig(): Config { if (typeof window === "undefined") return { ownerName: "", businessName: "", pan: "", upiId: "", netlifyToken: "", projectRate: "7500" }; try { return { ownerName: "", businessName: "", pan: "", upiId: "", netlifyToken: "", projectRate: "7500", ...JSON.parse(window.localStorage.getItem(CONFIG_KEY) ?? "{}") }; } catch { return { ownerName: "", businessName: "", pan: "", upiId: "", netlifyToken: "", projectRate: "7500" }; } }
function saveLead(lead: Lead) { const next = [...getSavedLeads().filter((item) => item.id !== lead.id), lead]; window.localStorage.setItem(STORAGE_KEY, JSON.stringify(next)); window.dispatchEvent(new Event("jarvis-leads-updated")); return next; }
function saveLeads(leads: Lead[]) { window.localStorage.setItem(STORAGE_KEY, JSON.stringify(leads)); window.dispatchEvent(new Event("jarvis-leads-updated")); }
function updateLead(id: string, patch: Partial<Lead>) { saveLeads(getSavedLeads().map((lead) => lead.id === id ? { ...lead, ...patch } : lead)); }
function formatCurrency(value: number) { return new Intl.NumberFormat("en-IN", { style: "currency", currency: "INR", maximumFractionDigits: 0 }).format(value); }
function conservativeRevenue(leads: Lead[]) { const rate = Number(getConfig().projectRate) || 0; return leads.filter((lead) => lead.probability >= 70).reduce((sum, lead) => sum + (lead.value || rate), 0); }
function stageTone(stage: Stage) { return { New: "neutral", Contacted: "blue", Interested: "amber", Proposal: "violet", Won: "green", Lost: "red" }[stage]; }
function StatusBadge({ stage }: { stage: Stage }) { return <span className={cn("badge", `badge-${stageTone(stage)}`)}>{stage}</span>; }
function isOverdue(lead: Lead) { return !!lead.followUpDate && new Date(`${lead.followUpDate}T23:59:59`).getTime() < Date.now(); }
function probabilityFor(rating?: number, reviews?: number, website?: string) { return Math.min(95, Math.max(18, Math.round((rating ?? 3.8) * 13 + Math.min(20, Math.log10((reviews ?? 10) + 1) * 5) + (website ? 10 : 0)))); }
function scoreFor(probability: number, website?: string, phone?: string) { return Math.min(99, Math.round(probability * .7 + (website ? 15 : 0) + (phone ? 10 : 0))); }
function normalizePhone(phone?: string) { return (phone ?? "").replace(/\D/g, "").replace(/^0+/, ""); }
function normalizeText(value?: string) { return (value ?? "").toLowerCase().replace(/https?:\/\/(www\.)?/, "").replace(/[^a-z0-9]/g, ""); }
function duplicateOf(candidate: Lead, existing = getSavedLeads()) { return existing.find((lead) => (candidate.phone && normalizePhone(candidate.phone) && normalizePhone(candidate.phone) === normalizePhone(lead.phone)) || normalizeText(candidate.business) === normalizeText(lead.business) || (candidate.website && lead.website && normalizeText(candidate.website) === normalizeText(lead.website))); }
function bumpMetric(key: "messages" | "replies" | "deals") { const current = JSON.parse(window.localStorage.getItem(METRICS_KEY) ?? "{}"); current[key] = (current[key] ?? 0) + 1; current.date = new Date().toISOString().slice(0, 10); window.localStorage.setItem(METRICS_KEY, JSON.stringify(current)); }
function todayISO() { return new Date().toISOString().slice(0, 10); }
function outreachFor(lead: Lead, tone: Tone = "Casual") { const name = lead.business; if (tone === "Hindi") return `नमस्ते ${name}, आपकी ऑनलाइन presence देखी। मैं Hyderabad में web experiences बनाता हूँ और आपकी website को अधिक enquiries के लिए बेहतर करने के कुछ ideas साझा कर सकता हूँ। क्या इस सप्ताह 15 मिनट की बातचीत संभव है?`; if (tone === "Telugu") return `నమస్కారం ${name}, మీ online presence చూసాను. Hyderabadలో businesses కోసం websites మరియు lead systems నిర్మిస్తాను. మీకు 15 నిమిషాల quick review ఈ వారం సరిపోతుందా?`; const core = `Hi ${name}, I found your business while looking around ${lead.location}. I help local teams turn more website visits into enquiries. I noted a few practical opportunities for your online presence — open to a 15-minute review this week?`; if (tone === "Formal") return `Hello ${name}, I work with businesses in ${lead.location} on clearer websites and conversion flows. I have identified a few practical opportunities for your online presence. Would a 15-minute review this week be useful?`; if (tone === "Short") return `Hi ${name}, I found a few ways to improve your website enquiries. Open to a 15-minute review this week?`; if (tone === "Long") return `${core}\n\nI can share a short audit first, with no obligation. If it is useful, we can discuss a focused project around the highest-impact changes.`; return core; }

function Shell({ children, onThemeToggle, light }: { children: ReactNode; onThemeToggle: () => void; light: boolean }) {
  const [location, setLocation] = useLocation(); const current = location === "/" ? "/" : `/${location.split("/")[1]}`; const [collapsed, setCollapsed] = useState(false); const [commandOpen, setCommandOpen] = useState(false); const [searchTerm, setSearchTerm] = useState("");
  useEffect(() => { const onKey = (event: KeyboardEvent) => { if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") { event.preventDefault(); setCommandOpen(true); } if (event.key === "Escape") setCommandOpen(false); }; window.addEventListener("keydown", onKey); return () => window.removeEventListener("keydown", onKey); }, []);
  const commandResults = navSections.flatMap((section) => section.items).filter((item) => item.label.toLowerCase().includes(searchTerm.toLowerCase()));
  const leadResults = getSavedLeads().filter((lead) => lead.business.toLowerCase().includes(searchTerm.toLowerCase()));
  return <div className={cn("app-shell", collapsed && "sidebar-collapsed")}><aside className="sidebar"><div className="sidebar-top"><button className="brand" onClick={() => setLocation("/")}><span className="brand-mark">J</span><span className="brand-name">jarvis</span></button><button className="icon-button sidebar-collapse" onClick={() => setCollapsed((v) => !v)}><PanelLeftClose size={16} /></button></div><div className="workspace-switcher"><span className="workspace-avatar">M</span><span className="workspace-copy"><strong>{getConfig().businessName || "Meridian Studio"}</strong><small>Hyderabad, India</small></span><ChevronDown size={14} className="muted-icon" /></div><nav className="nav-groups">{navSections.map((section) => <div className="nav-group" key={section.label}><div className="nav-section-label">{section.label}</div>{section.items.map((item) => { const Icon = item.icon; return <button key={item.href} className={cn("nav-item", current === item.href && "nav-item-active")} onClick={() => setLocation(item.href)}><Icon size={16} strokeWidth={1.7} /><span>{item.label}</span></button>; })}</div>)}</nav><div className="sidebar-bottom"><div className="live-stat"><span className="live-dot" /><span>System online</span><span className="stat-value mono">100%</span></div><div className="sidebar-stat"><span>Saved leads</span><strong>{getSavedLeads().length}</strong></div><div className="sidebar-stat"><span>Follow-ups due</span><strong>{getSavedLeads().filter((lead) => isOverdue(lead) || lead.followUpDate === todayISO()).length}</strong></div><button className="profile-row"><span className="profile-avatar">MC</span><span className="profile-copy"><strong>{getConfig().ownerName || "Workspace owner"}</strong><small>Owner</small></span><MoreHorizontal size={15} className="muted-icon" /></button></div></aside><main className="main-area"><header className="topbar"><div className="breadcrumbs"><span>Meridian Studio</span><ChevronRight size={14} /><strong>{getPageTitle(current)}</strong></div><div className="topbar-actions"><button className="command-trigger" onClick={() => setCommandOpen(true)}><Search size={14} /><span>Search anything</span><kbd>⌘ K</kbd></button><button className="icon-button" onClick={onThemeToggle}>{light ? <Moon size={16} /> : <Sun size={16} />}</button><button className="icon-button" onClick={() => toast("No new notifications")}><Bell size={16} /></button></div></header><div className="page-content">{children}</div></main>{commandOpen && <div className="command-overlay" onMouseDown={() => setCommandOpen(false)}><div className="command-dialog" onMouseDown={(e) => e.stopPropagation()}><div className="command-search"><Search size={16} /><input autoFocus placeholder="Try score, add, or a business name" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} /><kbd>ESC</kbd></div><div className="command-results"><div className="command-label">Actions</div><button onClick={() => { setLocation("/find-leads"); setCommandOpen(false); }}><Search size={15} /><span>Find leads</span><kbd>F</kbd></button><button onClick={() => { toast("Scoring queued for saved leads"); setCommandOpen(false); }}><Gauge size={15} /><span>Score leads</span><kbd>S</kbd></button><div className="command-label">Jump to</div>{commandResults.map((item) => { const Icon = item.icon; return <button key={item.href} onClick={() => { setLocation(item.href); setCommandOpen(false); }}><Icon size={15} /><span>{item.label}</span><ChevronRight size={14} /></button>; })}{leadResults.map((lead) => <button key={lead.id} onClick={() => { setLocation("/pipeline"); setCommandOpen(false); toast(`${lead.business} selected`); }}><Users size={15} /><span>{lead.business}</span><small>{lead.id}</small></button>)}</div><div className="command-footer"><span><kbd>↑↓</kbd> Navigate</span><span><kbd>↵</kbd> Open</span><span><kbd>ESC</kbd> Close</span></div></div></div>}</div>;
}
function getPageTitle(path: string) { return navSections.flatMap((s) => s.items).find((i) => i.href === path)?.label ?? "Dashboard"; }
function PageHeader({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description?: string; action?: ReactNode }) { return <div className="page-header"><div><div className="eyebrow">{eyebrow ?? "Workspace"}</div><h1>{title}</h1>{description && <p>{description}</p>}</div>{action && <div className="page-header-action">{action}</div>}</div>; }
function MetricCard({ label, value, delta, direction, note, icon: Icon }: { label: string; value: string; delta: string; direction: "up" | "down"; note: string; icon: ElementType }) { return <div className="metric-card"><div className="metric-top"><span className="metric-label">{label}</span><Icon size={16} className="muted-icon" /></div><div className="metric-value">{value}</div><div className="metric-meta"><span className={direction === "up" ? "delta-up" : "delta-down"}>{direction === "up" ? <ArrowUpRight size={13} /> : <ArrowDownRight size={13} />}{delta}</span><span>{note}</span></div></div>; }
function EmptyState({ message, action, onAction }: { message: string; action: string; onAction: () => void }) { return <div className="empty-state"><span>{message}</span><button className="text-button" onClick={onAction}>{action} <ChevronRight size={14} /></button></div>; }
function SortBar({ sort, setSort, options = ["Newest", "Probability", "Score", "Business"] }: { sort: string; setSort: (value: string) => void; options?: string[] }) { return <label className="sort-control"><ArrowDownUp size={13} /><span>Sort</span><select value={sort} onChange={(e) => setSort(e.target.value)}>{options.map((option) => <option key={option}>{option}</option>)}</select></label>; }
function sortedLeads(leads: Lead[], sort: string) { return [...leads].sort((a, b) => sort === "Probability" ? b.probability - a.probability : sort === "Score" ? b.score - a.score : sort === "Business" ? a.business.localeCompare(b.business) : (b.lastTouch ?? "").localeCompare(a.lastTouch ?? "")); }

function Dashboard() { const [, setLocation] = useLocation(); const [tick, setTick] = useState(0); useEffect(() => { const fn = () => setTick((v) => v + 1); window.addEventListener("jarvis-leads-updated", fn); return () => window.removeEventListener("jarvis-leads-updated", fn); }, []); const savedLeads = getSavedLeads(); const pipelineValue = savedLeads.reduce((sum, lead) => sum + lead.value, 0); const conservative = conservativeRevenue(savedLeads); void tick; return <><PageHeader eyebrow="Overview" title="Dashboard" description="A quiet view of the work that needs attention." action={<><button className="button secondary" onClick={() => toast(savedLeads.length ? "Export prepared" : "There is no data to export yet")}>Export CSV</button><button className="button primary" onClick={() => setLocation("/find-leads")}><Search size={15} /> Find leads</button></>} /><section className="metric-grid"><MetricCard label="Open pipeline" value={formatCurrency(pipelineValue)} delta={savedLeads.length ? `${savedLeads.length}` : "—"} direction="up" note={savedLeads.length ? "saved leads" : "no leads yet"} icon={Target} /><MetricCard label="Conservative upside" value={formatCurrency(conservative)} delta={savedLeads.filter((lead) => lead.probability >= 70).length ? `${savedLeads.filter((lead) => lead.probability >= 70).length}` : "—"} direction="up" note="70%+ probability only" icon={ShieldCheck} /><MetricCard label="Client probability" value={savedLeads.length ? `${Math.round(savedLeads.reduce((sum, lead) => sum + lead.probability, 0) / savedLeads.length)}%` : "—"} delta="—" direction="up" note="average saved lead" icon={Gauge} /><MetricCard label="Collected this month" value={formatCurrency(savedLeads.filter((lead) => lead.stage === "Won").reduce((sum, lead) => sum + lead.value, 0))} delta="—" direction="up" note="payments connect later" icon={Database} /><MetricCard label="Follow-ups due" value={String(savedLeads.filter((lead) => isOverdue(lead) || lead.followUpDate === todayISO()).length)} delta="—" direction="down" note="today or overdue" icon={Clock3} /></section><section className="dashboard-grid"><div className="panel pipeline-panel"><div className="panel-header"><div><h2>Pipeline</h2><p>Current lead distribution by stage.</p></div><button className="text-button" onClick={() => setLocation("/pipeline")}>View pipeline <ChevronRight size={14} /></button></div><div className="pipeline-total"><strong>{formatCurrency(pipelineValue)}</strong><span>saved value</span></div><div className={cn("pipeline-bar", !savedLeads.length && "pipeline-bar-empty")}>{savedLeads.length > 0 && stages.map((stage) => <span key={stage} className={`bar-${stageTone(stage)}`} style={{ width: `${Math.max(3, (savedLeads.filter((lead) => lead.stage === stage).length / savedLeads.length) * 100)}%` }} />)}</div>{savedLeads.length ? <div className="legend-grid">{stages.map((stage) => <div className="legend-item" key={stage}><span className={cn("legend-dot", `dot-${stageTone(stage)}`)} /><span>{stage}</span><strong>{savedLeads.filter((lead) => lead.stage === stage).length}</strong></div>)}</div> : <EmptyState message="No leads in the pipeline." action="Find leads" onAction={() => setLocation("/find-leads")} />}</div><div className="panel activity-panel"><div className="panel-header"><div><h2>Today</h2><p>The work queue for the current day.</p></div><button className="text-button" onClick={() => setLocation("/today")}>Open <ChevronRight size={14} /></button></div><EmptyState message={savedLeads.length ? "No activity logged yet." : "No activity yet."} action="Find leads" onAction={() => setLocation("/find-leads")} /></div></section><section className="panel table-panel"><div className="panel-header"><div><h2>Hot leads</h2><p>Qualified opportunities saved from your area searches.</p></div><button className="text-button" onClick={() => setLocation("/find-leads")}>Find leads <ChevronRight size={14} /></button></div>{savedLeads.length ? <LeadTable leads={savedLeads.filter((lead) => lead.probability >= 70).slice(0, 5)} /> : <EmptyState message="No leads yet." action="Find leads" onAction={() => setLocation("/find-leads")} />}</section></>; }

function FindLeads() { const [area, setArea] = useState("Secunderabad, Hyderabad"); const [query, setQuery] = useState("web design agencies"); const [radius, setRadius] = useState("5000"); const [map, setMap] = useState<google.maps.Map | null>(null); const [results, setResults] = useState<Lead[]>([]); const [searching, setSearching] = useState(false); const [searched, setSearched] = useState(false); const [error, setError] = useState(""); const [addedIds, setAddedIds] = useState<string[]>(() => getSavedLeads().map((lead) => lead.id)); const [sort, setSort] = useState("Probability"); const markers = useMemo(() => [] as google.maps.Marker[], []);
  const addLead = (lead: Lead) => { if (duplicateOf(lead)) { toast("Possible duplicate detected — review the existing lead first"); return; } saveLead(lead); setAddedIds((ids) => ids.includes(lead.id) ? ids : [...ids, lead.id]); toast.success(`${lead.business} added to New`); };
  const addAll = () => { const fresh = results.filter((lead) => !duplicateOf(lead)); const duplicates = results.length - fresh.length; fresh.forEach((lead) => saveLead(lead)); setAddedIds((ids) => Array.from(new Set([...ids, ...fresh.map((lead) => lead.id)]))); toast.success(`${fresh.length} businesses added${duplicates ? ` · ${duplicates} duplicates skipped` : ""}`); };
  const search = async () => { if (!map || !area.trim() || !query.trim()) return; setSearching(true); setError(""); setSearched(true); setResults([]); try { const geocoder = new google.maps.Geocoder(); const geocode = await new Promise<google.maps.GeocoderResult>((resolve, reject) => geocoder.geocode({ address: `${area}, Telangana, India` }, (items, status) => items?.[0] && status === "OK" ? resolve(items[0]) : reject(new Error("Area not found")))); const center = geocode.geometry.location; map.setCenter(center); map.setZoom(13); const service = new google.maps.places.PlacesService(map); const found = await new Promise<google.maps.places.PlaceResult[]>((resolve, reject) => service.textSearch({ query: `${query} near ${area}, Hyderabad, Telangana, India`, location: center, radius: Number(radius) }, (items, status) => status === google.maps.places.PlacesServiceStatus.OK ? resolve(items ?? []) : reject(new Error(status === "ZERO_RESULTS" ? "No businesses found in this area." : "Places search failed.")))); found.slice(0, 20).forEach((place) => { if (place.geometry?.location) markers.push(new google.maps.Marker({ map, position: place.geometry.location, title: place.name })); }); const mapped = await Promise.all(found.slice(0, 20).map(async (place, index) => { const details = place.place_id ? await new Promise<google.maps.places.PlaceResult>((resolve) => service.getDetails({ placeId: place.place_id as string, fields: ["name", "formatted_address", "website", "formatted_phone_number", "international_phone_number", "rating", "user_ratings_total"] }, (detail) => resolve(detail ?? place))) : place; const probability = probabilityFor(details.rating, details.user_ratings_total, details.website); return { id: details.place_id ?? `place-${index}`, business: details.name ?? "Unnamed business", niche: query, location: details.formatted_address ?? area, score: scoreFor(probability, details.website, details.international_phone_number ?? details.formatted_phone_number), probability, contact: "Not enriched", phone: details.international_phone_number ?? details.formatted_phone_number, lastTouch: "Found just now", value: 0, initials: (details.name ?? "B").split(" ").slice(0, 2).map((word) => word[0]).join("").toUpperCase(), address: details.formatted_address, website: details.website, placeId: details.place_id, stage: "New" as Stage, followUpDate: todayISO(), replyStatus: "none" as const, source: "Google Places" }; })); setResults(mapped); if (!mapped.length) setError("No businesses found in this area."); } catch (err) { setError(err instanceof Error ? err.message : "Search failed. Try a more specific area."); } finally { setSearching(false); } };
  return <><PageHeader eyebrow="Lead discovery" title="Find leads" description="Search Google Places for businesses around any area, with probability estimates before you save them." action={<SortBar sort={sort} setSort={setSort} />} /><div className="finder-layout"><section className="finder-panel"><div className="finder-controls"><label>Area<input value={area} onChange={(e) => setArea(e.target.value)} placeholder="Secunderabad, Hyderabad" /></label><label>Business type<input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="e.g. dental clinics" /></label><label>Radius<select value={radius} onChange={(e) => setRadius(e.target.value)}><option value="2000">2 km</option><option value="5000">5 km</option><option value="10000">10 km</option></select></label><button className="button primary finder-search" onClick={search} disabled={searching || !map}>{searching ? <><RefreshCw size={15} className="spin" /> Searching</> : <><Search size={15} /> Search area</>}</button></div><div className="map-frame"><MapView className="finder-map" initialCenter={{ lat: 17.4399, lng: 78.4983 }} initialZoom={12} onMapReady={setMap} /><div className="map-overlay-note"><span className="live-dot" /> Google Places · live search</div></div></section><section className="finder-results"><div className="panel-header"><div><h2>{searched ? `${results.length} businesses found` : "Search results"}</h2><p>{searched ? `Around ${area}` : "Specify an area and business type to begin."}</p></div>{results.length > 0 && <button className="text-button" onClick={addAll}>Add all <ChevronRight size={14} /></button>}</div>{error && <div className="finder-error">{error}</div>}{!searched && <div className="finder-empty"><Search size={18} /><strong>Find businesses around you</strong><span>Try “interior designers” in “Banjara Hills, Hyderabad”.</span></div>}{searched && !results.length && !error && <div className="finder-empty"><RefreshCw size={18} /><strong>Searching Places</strong><span>Results will appear here.</span></div>}{sortedLeads(results, sort).map((lead) => <div className="finder-result" key={lead.id}><div className="lead-avatar">{lead.initials}</div><div className="finder-result-copy"><strong>{lead.business}</strong><small>{lead.address ?? lead.location}</small><small className="probability-line">{lead.probability}% likely to become a client · score {lead.score}</small></div><button className="row-action" disabled={addedIds.includes(lead.id) || !!duplicateOf(lead)} onClick={() => addLead(lead)}>{addedIds.includes(lead.id) || duplicateOf(lead) ? <Check size={16} /> : <Plus size={16} />}</button></div>)}</section></div></>; }

function AddLeads() { const [tab, setTab] = useState("Single"); const [name, setName] = useState(""); const [url, setUrl] = useState(""); const [phone, setPhone] = useState(""); const [email, setEmail] = useState(""); const [notes, setNotes] = useState(""); const [duplicates, setDuplicates] = useState<Lead[]>([]); const submit = (e: FormEvent) => { e.preventDefault(); const candidate: Lead = { id: `manual-${Date.now()}`, business: name, niche: "Manual lead", location: "Hyderabad, Telangana", score: 50, probability: 40, stage: "New", contact: "Not enriched", phone, email, lastTouch: "Added just now", value: 0, initials: name.split(" ").slice(0, 2).map((word) => word[0]).join("").toUpperCase(), website: url, followUpDate: todayISO(), replyStatus: "none", source: "Manual" }; const duplicate = duplicateOf(candidate); if (duplicate) { setDuplicates([duplicate]); return; } saveLead(candidate); toast.success("Lead added to New"); setName(""); setUrl(""); setPhone(""); setEmail(""); setNotes(""); }; return <><PageHeader eyebrow="Lead intake" title="Add leads" description="Add a known business or bring in a prepared list. Duplicate checks run before saving." /><div className="tabs-line">{["Single", "Paste links", "Paste Maps details"].map((item) => <button key={item} className={cn("tab-button", tab === item && "tab-active")} onClick={() => setTab(item)}>{item}</button>)}</div><div className="split-layout"><form className="form-section" onSubmit={submit}><div className="form-block"><div className="form-label">{tab === "Single" ? "Business details" : "Source input"}</div>{tab === "Single" ? <><label>Business name<input value={name} onChange={(e) => setName(e.target.value)} placeholder="e.g. a Hyderabad design studio" required /></label><div className="form-row"><label>Website<input value={url} onChange={(e) => setUrl(e.target.value)} placeholder="company.in" /></label><label>Phone<input value={phone} onChange={(e) => setPhone(e.target.value)} placeholder="+91 98 0000 0000" /></label><label>Email<input value={email} onChange={(e) => setEmail(e.target.value)} placeholder="owner@company.in" type="email" /></label></div></> : <label>{tab === "Paste links" ? "Website links" : "Google Maps details"}<textarea value={url} onChange={(e) => setUrl(e.target.value)} placeholder={tab === "Paste links" ? "Paste one URL per line" : "Paste copied Maps results here"} rows={7} required /></label>}<label>Notes<textarea value={notes} onChange={(e) => setNotes(e.target.value)} placeholder="Context for the next step" rows={4} /></label></div><div className="form-footer"><button type="button" className="button secondary" onClick={() => { setName(""); setUrl(""); setPhone(""); setEmail(""); setNotes(""); }}>Clear</button><button type="submit" className="button primary"><Plus size={15} /> {tab === "Single" ? "Add lead" : "Queue import"}</button></div>{duplicates.length > 0 && <div className="duplicate-warning"><ShieldCheck size={15} /><span>Possible duplicate found: {duplicates[0].business}. <button className="text-button" onClick={() => { saveLead({ ...duplicates[0], lastTouch: "Merged just now" }); setDuplicates([]); }}>Merge</button> or <button className="text-button" onClick={() => setDuplicates([])}>Skip</button></span></div>}</form><aside className="helper-panel"><div className="helper-icon"><Target size={16} /></div><h2>Duplicate protection is on</h2><p>Phone, business name, and website are checked against saved leads before inserting.</p><div className="helper-list"><div><Check size={14} /> Follow-up date defaults to today</div><div><Check size={14} /> Probability starts conservative</div><div><Check size={14} /> WhatsApp stays one click away</div></div></aside></div></>; }

function Today() { const [, setLocation] = useLocation(); const [sort, setSort] = useState("Probability"); const [permission, setPermission] = useState(typeof Notification !== "undefined" ? Notification.permission : "default"); const leads = sortedLeads(getSavedLeads(), sort); const due = leads.filter((lead) => isOverdue(lead) || lead.followUpDate === todayISO()); const hot = leads.filter((lead) => lead.stage === "New" && lead.score >= 70); const waiting = leads.filter((lead) => lead.replyStatus === "waiting"); const proposals = leads.filter((lead) => lead.stage === "Proposal" && lead.proposalSentAt && Date.now() - new Date(lead.proposalSentAt).getTime() > 3 * 86400000); const metrics = JSON.parse(window.localStorage.getItem(METRICS_KEY) ?? "{}"); const enableNotifications = async () => { if (typeof Notification === "undefined") return toast("Browser notifications are not supported"); const result = await Notification.requestPermission(); setPermission(result); if (result === "granted") new Notification("Jarvis reminders enabled", { body: `${due.length} follow-up${due.length === 1 ? "" : "s"} due today.` }); }; useEffect(() => { const now = new Date(); const target = new Date(now); target.setHours(10, 0, 0, 0); if (target <= now) target.setDate(target.getDate() + 1); const timer = window.setTimeout(() => { if (typeof Notification !== "undefined" && Notification.permission === "granted") new Notification("Jarvis follow-ups", { body: `${due.length} follow-up${due.length === 1 ? "" : "s"} due today.` }); }, target.getTime() - now.getTime()); return () => window.clearTimeout(timer); }, [due.length]); return <><PageHeader eyebrow="Daily workflow" title="Today" description="One screen for the follow-ups, replies, proposals, and targets that matter now." action={<><SortBar sort={sort} setSort={setSort} /><button className="button secondary" onClick={enableNotifications}>{permission === "granted" ? <Check size={14} /> : <Bell size={14} />} {permission === "granted" ? "Reminders on" : "Enable reminders"}</button></>} /><div className="today-grid"><TodaySection title="Follow-ups due" count={due.length} description="Today or overdue" leads={due} empty="No follow-ups due." onAction={() => setLocation("/find-leads")} /><TodaySection title="Hot new leads" count={hot.length} description="Score ≥ 70 · not contacted" leads={hot} empty="No hot new leads." onAction={() => setLocation("/find-leads")} /><TodaySection title="Replies waiting" count={waiting.length} description="Respond before momentum drops" leads={waiting} empty="No replies waiting." onAction={() => setLocation("/pipeline")} /><TodaySection title="Proposals aging" count={proposals.length} description="Sent more than 3 days ago" leads={proposals} empty="No aging proposals." onAction={() => setLocation("/pipeline")} /></div><section className="panel daily-targets"><div className="panel-header"><div><h2>Daily targets</h2><p>Messages, replies, and deals against the current day.</p></div></div><div className="target-grid"><TargetRow label="Messages sent" actual={metrics.date === todayISO() ? metrics.messages ?? 0 : 0} target={30} /><TargetRow label="Replies" actual={metrics.date === todayISO() ? metrics.replies ?? 0 : 0} target={5} /><TargetRow label="Deals" actual={metrics.date === todayISO() ? metrics.deals ?? 0 : 0} target={1} /></div></section></>; }
function TodaySection({ title, count, description, leads, empty, onAction }: { title: string; count: number; description: string; leads: Lead[]; empty: string; onAction: () => void }) { return <section className="panel today-section"><div className="panel-header"><div><h2>{title} <span className="section-count">{count}</span></h2><p>{description}</p></div></div>{leads.length ? <div className="today-leads">{leads.slice(0, 5).map((lead) => <div className={cn("today-lead", isOverdue(lead) && "overdue-row")} key={lead.id}><span className="lead-avatar">{lead.initials}</span><span className="today-lead-copy"><strong>{lead.business}</strong><small>{lead.location} · {lead.probability}% likely</small></span><button className="row-action" onClick={() => sendWhatsApp(lead)}><Send size={14} /></button></div>)}</div> : <EmptyState message={empty} action="Find leads" onAction={onAction} />}</section>; }
function TargetRow({ label, actual, target }: { label: string; actual: number; target: number }) { const progress = Math.min(100, Math.round((actual / target) * 100)); return <div className="target-row"><span><strong>{label}</strong><small>{actual} of {target}</small></span><span className="target-track"><i style={{ width: `${progress}%` }} /></span><b>{progress}%</b></div>; }

function sendWhatsApp(lead: Lead) { if (!lead.phone) return toast("No phone number was returned for this business"); const message = encodeURIComponent(lead.outreach || outreachFor(lead)); bumpMetric("messages"); updateLead(lead.id, { stage: lead.stage === "New" ? "Contacted" : lead.stage, lastTouch: "WhatsApp opened", outreach: decodeURIComponent(message) }); window.open(`https://wa.me/${normalizePhone(lead.phone)}?text=${message}`, "_blank", "noopener,noreferrer"); }
function generateInvoice(lead: Lead) { const config = getConfig(); const doc = new jsPDF(); doc.setFont("helvetica", "bold"); doc.setFontSize(20); doc.text(config.businessName || "Invoice", 20, 25); doc.setFont("helvetica", "normal"); doc.setFontSize(10); doc.text(`Invoice date: ${new Date().toLocaleDateString("en-IN")}`, 20, 34); doc.text(`Client: ${lead.business}`, 20, 50); doc.text(`Project: Website and conversion improvements`, 20, 60); doc.text(`Amount: ${formatCurrency(lead.value || Number(config.projectRate) || 7500)}`, 20, 70); doc.text("Payment terms: 50% advance to begin. Balance on delivery.", 20, 85); doc.text(`PAN: ${config.pan || "Add PAN in Settings"}`, 20, 100); doc.text(`UPI: ${config.upiId || "Add UPI ID in Settings"}`, 20, 110); doc.save(`${lead.business.replace(/[^a-z0-9]+/gi, "-").toLowerCase()}-invoice.pdf`); toast.success("Invoice PDF downloaded"); }
function paymentLink(lead: Lead) { const config = getConfig(); if (!config.upiId) return toast("Add your UPI ID in Settings first"); const amount = lead.value || Number(config.projectRate) || 7500; const link = `upi://pay?pa=${encodeURIComponent(config.upiId)}&pn=${encodeURIComponent(config.businessName || "Meridian Studio")}&am=${amount}&cu=INR&tn=${encodeURIComponent(`Website project · ${lead.business}`)}`; navigator.clipboard?.writeText(link); toast.success("UPI payment link copied"); window.open(`https://api.qrserver.com/v1/create-qr-code/?size=240x240&data=${encodeURIComponent(link)}`, "_blank", "noopener,noreferrer"); }
async function deployDemo(lead: Lead) { const config = getConfig(); if (!config.netlifyToken) return toast("Add a Netlify personal access token in Settings first"); try { const create = await fetch("https://api.netlify.com/api/v1/sites", { method: "POST", headers: { Authorization: `Bearer ${config.netlifyToken}`, "Content-Type": "application/json" }, body: JSON.stringify({ name: `jarvis-${lead.business.toLowerCase().replace(/[^a-z0-9]+/g, "-").slice(0, 30)}` }) }); const site = await create.json() as { id: string; ssl_url?: string; url?: string }; if (!create.ok) throw new Error(site.id || "Netlify site creation failed"); const html = `<!doctype html><html><head><meta charset="utf-8"><title>${lead.business} · website review</title><style>body{font-family:system-ui;max-width:720px;margin:80px auto;padding:24px;color:#202124}h1{font-size:42px;line-height:1.05}p{font-size:18px;line-height:1.6;color:#5f6368}</style></head><body><p>Website review for</p><h1>${lead.business}</h1><p>A focused digital presence for ${lead.location}. This demo was prepared by ${config.businessName || "Meridian Studio"}.</p></body></html>`; const deploy = await fetch(`https://api.netlify.com/api/v1/sites/${site.id}/deploys`, { method: "POST", headers: { Authorization: `Bearer ${config.netlifyToken}`, "Content-Type": "application/zip" }, body: zipSync({ "index.html": strToU8(html) }) }); if (!deploy.ok) throw new Error("Netlify deploy failed"); const url = site.ssl_url || site.url || `https://${site.id}.netlify.app`; updateLead(lead.id, { demoUrl: url }); toast.success("Demo deployed to Netlify"); window.open(url, "_blank", "noopener,noreferrer"); } catch (error) { toast.error(error instanceof Error ? error.message : "Netlify deployment failed"); } }

function LeadTable({ leads, onSelect, selectable = false }: { leads: Lead[]; onSelect?: (lead: Lead) => void; selectable?: boolean }) { const [selected, setSelected] = useState<string[]>([]); const [sort, setSort] = useState("Probability"); const rows = sortedLeads(leads, sort); const toggle = (id: string) => setSelected((ids) => ids.includes(id) ? ids.filter((item) => item !== id) : [...ids, id]); const bulk = (action: string) => { if (action === "delete") saveLeads(getSavedLeads().filter((lead) => !selected.includes(lead.id))); else if (action === "status") saveLeads(getSavedLeads().map((lead) => selected.includes(lead.id) ? { ...lead, stage: "Contacted" as Stage, lastTouch: "Bulk status change" } : lead)); else if (action === "score") saveLeads(getSavedLeads().map((lead) => selected.includes(lead.id) ? { ...lead, score: Math.max(lead.score, 78), probability: Math.max(lead.probability, 72) } : lead)); else if (action === "audit") saveLeads(getSavedLeads().map((lead) => selected.includes(lead.id) ? { ...lead, audit: `Audit prepared for ${lead.business}.` } : lead)); else if (action === "outreach") saveLeads(getSavedLeads().map((lead) => selected.includes(lead.id) ? { ...lead, outreach: outreachFor(lead) } : lead)); toast(`${action} completed for ${selected.length} leads`); setSelected([]); }; return <div className="table-wrap"><div className="table-toolbar"><SortBar sort={sort} setSort={setSort} />{selectable && selected.length > 0 && <div className="bulk-actions"><span>{selected.length} selected</span><button className="text-button" onClick={() => bulk("score")}>Score</button><button className="text-button" onClick={() => bulk("audit")}>Audit</button><button className="text-button" onClick={() => bulk("outreach")}>Outreach</button><button className="text-button" onClick={() => bulk("status")}>Contacted</button><button className="text-button danger-link" onClick={() => bulk("delete")}><Trash2 size={13} /> Delete</button></div>}</div><table className="data-table"><thead><tr>{selectable && <th className="checkbox-cell"><input type="checkbox" checked={selected.length === rows.length && rows.length > 0} onChange={() => setSelected(selected.length === rows.length ? [] : rows.map((lead) => lead.id))} /></th>}<th>Business</th><th>Probability</th><th>Stage</th><th>Follow-up</th><th>Phone</th><th className="align-right">Value</th><th /></tr></thead><tbody>{rows.length ? rows.map((lead) => <tr key={lead.id} className={cn(isOverdue(lead) && "overdue-row")} onClick={() => onSelect?.(lead)}>{selectable && <td className="checkbox-cell"><input type="checkbox" checked={selected.includes(lead.id)} onChange={() => toggle(lead.id)} onClick={(e) => e.stopPropagation()} /></td>}<td><div className="lead-cell"><span className="lead-avatar">{lead.initials}</span><span><strong>{lead.business}</strong><small>{lead.niche} · {lead.location}</small></span></div></td><td><span className="probability-cell"><span className="probability-ring">{lead.probability}</span>%</span></td><td><StatusBadge stage={lead.stage} /></td><td className={cn(isOverdue(lead) && "overdue-text")}>{lead.followUpDate || "Not set"}</td><td className="mono">{lead.phone || "—"}</td><td className="align-right mono">{formatCurrency(lead.value)}</td><td className="align-right"><button className="row-action" onClick={(e) => { e.stopPropagation(); sendWhatsApp(lead); }}><Send size={14} /></button></td></tr>) : <tr><td colSpan={8}><EmptyState message="No leads yet." action="Find leads" onAction={() => toast("Use Find leads from the sidebar")} /></td></tr>}</tbody></table></div>; }

function PipelineView() { const [selected, setSelected] = useState<Lead | null>(null); const [view, setView] = useState<"board" | "table">("board"); const savedLeads = getSavedLeads(); useEffect(() => { const onKey = (event: KeyboardEvent) => { if (!selected) return; const index = savedLeads.findIndex((lead) => lead.id === selected.id); if (event.key.toLowerCase() === "j") setSelected(savedLeads[(index + 1) % Math.max(1, savedLeads.length)] ?? selected); if (event.key.toLowerCase() === "k") setSelected(savedLeads[(index - 1 + savedLeads.length) % Math.max(1, savedLeads.length)] ?? selected); if (event.key.toLowerCase() === "s") { updateLead(selected.id, { score: Math.max(selected.score, 78), probability: Math.max(selected.probability, 72) }); toast.success("Lead scored"); } if (event.key.toLowerCase() === "a") { updateLead(selected.id, { audit: `Audit prepared for ${selected.business}. Review the current website clarity, mobile experience, and conversion path.` }); toast.success("Audit generated"); } if (event.key.toLowerCase() === "o") { const outreach = outreachFor(selected); updateLead(selected.id, { outreach }); toast.success("Outreach generated"); } if (event.key.toLowerCase() === "d") void deployDemo(selected); if (event.key.toLowerCase() === "p") { updateLead(selected.id, { proposalSentAt: new Date().toISOString(), stage: "Proposal" }); toast.success("Proposal marked as sent"); } if (event.key.toLowerCase() === "c") { navigator.clipboard?.writeText(selected.outreach || outreachFor(selected)); toast.success("Outreach copied"); } if (event.key.toLowerCase() === "w") sendWhatsApp(selected); if ((event.metaKey || event.ctrlKey) && event.key === "Enter") sendWhatsApp(selected); if (event.key.toLowerCase() === "x") toast("Lead row selected"); }; window.addEventListener("keydown", onKey); return () => window.removeEventListener("keydown", onKey); }, [selected, savedLeads]); return <><PageHeader eyebrow="Workspace" title="Pipeline" description="Move work forward with score, probability, follow-up, and outreach one click away." action={<button className="button primary" onClick={() => toast("Use Find leads to discover businesses")}><Search size={15} /> Find leads</button>} /><div className="toolbar"><div className="toolbar-left"><button className="filter-button"><Filter size={14} /> All leads <ChevronDown size={13} /></button><span className="toolbar-count">{savedLeads.length} leads</span></div><div className="view-toggle"><button className={cn(view === "board" && "view-active")} onClick={() => setView("board")}><KanbanSquare size={14} /> Board</button><button className={cn(view === "table" && "view-active")} onClick={() => setView("table")}><ListFilter size={14} /> Table</button></div></div>{view === "board" ? <div className="kanban-board">{stages.map((stage) => { const stageLeads = savedLeads.filter((lead) => lead.stage === stage); return <div className="kanban-column" key={stage}><div className="kanban-header"><span><span className={cn("legend-dot", `dot-${stageTone(stage)}`)} />{stage}</span><span className="column-count">{stageLeads.length}</span></div><div className="kanban-cards">{stageLeads.map((lead) => <button className={cn("lead-card", isOverdue(lead) && "overdue-card")} key={lead.id} onClick={() => setSelected(lead)}><div className="lead-card-top"><span className="mono lead-id">{lead.id}</span><span className="probability-chip">{lead.probability}% likely</span></div><strong>{lead.business}</strong><span className="lead-card-meta">{lead.niche}</span><div className="lead-card-footer"><span>{lead.followUpDate || "No follow-up"}</span><span className="mono">{formatCurrency(lead.value)}</span></div></button>)}{!stageLeads.length && <div className="column-empty">No leads in this stage.</div>}</div><button className="column-add" onClick={() => toast("Use Find leads to add businesses")}><Plus size={14} /> Add lead</button></div>; })}</div> : <section className="panel table-panel"><LeadTable leads={savedLeads} selectable onSelect={setSelected} /></section>}{selected && <LeadDrawer lead={selected} onClose={() => setSelected(null)} />}</>; }

function LeadDrawer({ lead, onClose }: { lead: Lead; onClose: () => void }) {
  const [tone, setTone] = useState<Tone>("Casual");
  const [kind, setKind] = useState<"outreach" | "audit" | "proposal">("outreach");
  const [output, setOutput] = useState(lead.outreach || outreachFor(lead));
  const [tab, setTab] = useState("Overview");
  const emailMutation = trpc.email.send.useMutation({ onSuccess: (result) => toast.success(`Email sent via ${result.provider}`), onError: (error) => toast.error(error.message || "Email send failed") });
  const aiMutation = trpc.ai.generate.useMutation({
    onSuccess: (result) => {
      setOutput(result.text);
      if (result.kind === "outreach") updateLead(lead.id, { outreach: result.text });
      if (result.kind === "audit") updateLead(lead.id, { audit: result.text });
      if (result.kind === "proposal") updateLead(lead.id, { proposal: result.text, proposalSentAt: new Date().toISOString() });
      toast.success(`${result.kind[0].toUpperCase()}${result.kind.slice(1)} generated with ${result.model}`);
    },
    onError: (error) => toast.error(error.message || "AI generation failed"),
  });
  const generate = (requestedKind = kind) => aiMutation.mutate({ kind: requestedKind, tone, lead: { id: lead.id, business: lead.business, niche: lead.niche, location: lead.location, website: lead.website, score: lead.score, probability: lead.probability, stage: lead.stage } });
  const sendEmail = () => { if (!lead.email) return toast("Add an email address to this lead first"); if (!output.trim()) return toast("Generate or write an email body first"); emailMutation.mutate({ leadId: lead.id, to: lead.email, subject: `A quick idea for ${lead.business}`, body: output }); };
  const openOutput = (nextKind: "outreach" | "audit" | "proposal") => { setKind(nextKind); setTab(nextKind === "outreach" ? "Outreach" : nextKind === "audit" ? "Audit" : "Proposal"); };
  const outputLabel = kind === "outreach" ? "Outreach message" : kind === "audit" ? "Website audit" : "Proposal outline";
  return <div className="drawer-overlay" onMouseDown={onClose}><aside className="lead-drawer" onMouseDown={(e) => e.stopPropagation()}><div className="drawer-header"><div><div className="eyebrow">{lead.id}</div><h2>{lead.business}</h2><p>{lead.niche} · {lead.location}</p></div><div className="drawer-actions"><span className="probability-chip">{lead.probability}% likely</span><button className="icon-button" onClick={onClose}><X size={17} /></button></div></div><div className="drawer-tabs">{["Overview", "Outreach", "Audit", "Proposal", "Commercial"].map((item) => <button key={item} className={cn(tab === item && "drawer-tab-active")} onClick={() => { setTab(item); if (item === "Outreach") setKind("outreach"); if (item === "Audit") setKind("audit"); if (item === "Proposal") setKind("proposal"); }}>{item}</button>)}</div><div className="drawer-body">{tab === "Overview" && <><div className="drawer-grid"><div><span className="micro-label">Probability</span><strong className="drawer-score">{lead.probability}<small>%</small></strong></div><div><span className="micro-label">Score</span><strong className="drawer-stat">{lead.score}/100</strong></div><div><span className="micro-label">Follow-up</span><strong className={cn("drawer-stat", isOverdue(lead) && "overdue-text")}>{lead.followUpDate || "Not set"}</strong></div><div><span className="micro-label">Phone</span><strong className="drawer-stat mono">{lead.phone || "Not returned"}</strong></div></div><div className="detail-divider" /><div className="drawer-section"><div className="drawer-section-head"><h3>AI workspace</h3><span className="ai-live-label"><span className="live-dot" /> Server-side AI</span></div><p className="drawer-help">Generate a reviewable message, audit, or proposal through the server-side AI gateway. Nothing is sent automatically.</p><div className="drawer-action-grid"><button className="button secondary" onClick={() => { openOutput("outreach"); generate("outreach"); }}><Send size={14} /> Generate outreach</button><button className="button secondary" onClick={() => { openOutput("audit"); generate("audit"); }}><Gauge size={14} /> Generate audit</button><button className="button secondary" onClick={() => { openOutput("proposal"); generate("proposal"); }}><FileText size={14} /> Generate proposal</button><button className="button secondary" onClick={() => sendWhatsApp(lead)}><Send size={14} /> Send WhatsApp</button><button className="button secondary" onClick={sendEmail}><Send size={14} /> Send email</button></div></div><div className="drawer-section"><div className="drawer-section-head"><h3>Quick actions</h3></div><div className="drawer-action-grid"><button className="button secondary" onClick={() => { updateLead(lead.id, { followUpDate: new Date(Date.now() + 3 * 86400000).toISOString().slice(0, 10) }); toast("Follow-up snoozed 3 days"); }}><Clock3 size={14} /> Snooze 3 days</button><button className="button secondary" onClick={() => deployDemo(lead)}><ExternalLink size={14} /> {lead.demoUrl ? "Open demo" : "Deploy demo"}</button><button className="button secondary" onClick={() => generateInvoice(lead)}><FileText size={14} /> Generate invoice</button><button className="button secondary" onClick={() => paymentLink(lead)}><Copy size={14} /> Copy UPI + QR</button></div></div></>}{(tab === "Outreach" || tab === "Audit" || tab === "Proposal") && <div className="drawer-section"><div className="output-toolbar"><select value={kind} onChange={(e) => { const next = e.target.value as "outreach" | "audit" | "proposal"; setKind(next); }}>{["outreach", "audit", "proposal"].map((item) => <option key={item} value={item}>{item[0].toUpperCase() + item.slice(1)}</option>)}</select><select value={tone} onChange={(e) => setTone(e.target.value as Tone)}>{["Formal", "Casual", "Short", "Long", "Hindi", "Telugu"].map((item) => <option key={item}>{item}</option>)}</select><button className="button primary" disabled={aiMutation.isPending} onClick={() => generate()}>{aiMutation.isPending ? <><RefreshCw size={14} className="spin" /> Generating</> : <><Sparkles size={14} /> Generate with AI</>}</button><button className="button secondary" disabled={!output} onClick={() => { navigator.clipboard?.writeText(output); toast(`${outputLabel} copied`); }}><Copy size={14} /> Copy</button>{kind === "outreach" && <button className="button secondary" disabled={emailMutation.isPending} onClick={sendEmail}><Send size={14} /> {emailMutation.isPending ? "Sending" : "Send email"}</button>}</div><div className="ai-provider-note"><ShieldCheck size={14} /> Server-side generation · no API key in the browser</div><textarea value={output} onChange={(e) => setOutput(e.target.value)} rows={tab === "Outreach" ? 12 : 18} placeholder={`Generate a ${kind} for ${lead.business}`} /></div>}{tab === "Commercial" && <div className="drawer-section"><div className="commercial-card"><h3>Payment and proposal</h3><p>Use INR pricing, a 50% advance note, and UPI for faster handoff.</p><button className="button primary" onClick={() => generateInvoice(lead)}>Generate invoice PDF</button><button className="button secondary" onClick={() => paymentLink(lead)}>Generate UPI link + QR</button></div>{lead.demoUrl && <a className="demo-link" href={lead.demoUrl} target="_blank" rel="noreferrer"><ExternalLink size={14} /> {lead.demoUrl}</a>}</div>}</div><div className="drawer-footer"><button className="button secondary" onClick={onClose}>Close</button><button className="button primary" onClick={() => { const nextStage = lead.stage === "New" ? "Contacted" : lead.stage === "Contacted" ? "Interested" : lead.stage === "Interested" ? "Proposal" : lead.stage === "Proposal" ? "Won" : lead.stage; updateLead(lead.id, { stage: nextStage, lastTouch: "Moved forward" }); if (nextStage === "Won") bumpMetric("deals"); toast("Lead moved forward"); onClose(); }}>Move to next stage <ChevronRight size={15} /></button></div></aside></div>;
}

function AI_tools() { const operations = [{ title: "Website audit", description: "Review structure, clarity, and conversion friction.", icon: Gauge }, { title: "Enrich leads", description: "Fill gaps in business, contact, and market context.", icon: Sparkles }, { title: "Draft outreach", description: "Create a reviewable message with a tone preset.", icon: Send }, { title: "Generate proposal", description: "Turn a scoped opportunity into a reviewable proposal.", icon: FileText }]; const [sort, setSort] = useState("Business"); return <><PageHeader eyebrow="Operations" title="AI tools" description="Run focused operations across saved leads. Each output can be regenerated by tone." action={<SortBar sort={sort} setSort={setSort} options={["Business", "Newest"]} />} /><div className="tools-grid">{operations.map((operation) => { const Icon = operation.icon; return <div className="tool-card" key={operation.title}><div className="tool-card-top"><div className="tool-icon"><Icon size={17} /></div><span className="tool-status">Ready</span></div><h2>{operation.title}</h2><p>{operation.description}</p><div className="tool-meta"><span>{getSavedLeads().length} saved leads</span><span>Run when ready</span></div><button className="button secondary tool-run" onClick={() => toast(getSavedLeads().length ? `${operation.title} queued` : "Add or find leads first")}>Run operation <ChevronRight size={14} /></button></div>; })}</div></>; }

function Revenue() { const [sort, setSort] = useState("Business"); const leads = getSavedLeads().filter((lead) => lead.stage === "Won"); return <><PageHeader eyebrow="Operations" title="Revenue" description="Track Indian Rupee invoices and payments for your studio." action={<SortBar sort={sort} setSort={setSort} options={["Business", "Probability"]} />} /><div className="metric-grid revenue-metrics"><MetricCard label="Collected" value={formatCurrency(leads.reduce((sum, lead) => sum + lead.value, 0))} delta="—" direction="up" note="won leads" icon={Check} /><MetricCard label="Outstanding" value={formatCurrency(0)} delta="—" direction="down" note="no open invoices" icon={Clock3} /><MetricCard label="Clients" value={String(leads.length)} delta="—" direction="up" note="won leads" icon={Users} /><MetricCard label="Avg. deal" value={formatCurrency(leads.length ? leads.reduce((sum, lead) => sum + lead.value, 0) / leads.length : 0)} delta="—" direction="up" note="won leads" icon={BriefcaseBusiness} /></div><section className="panel table-panel"><div className="panel-header"><div><h2>Won work</h2><p>Currency: INR · GST-ready workflow · Hyderabad, Telangana.</p></div></div><LeadTable leads={sortedLeads(leads, sort)} /></section></>; }
function Logs() { const [sort, setSort] = useState("Newest"); const history = trpc.ai.history.useQuery({ limit: 50 }); const rows = [...(history.data ?? [])].sort((a, b) => sort === "Operation" ? a.kind.localeCompare(b.kind) : new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()); return <><PageHeader eyebrow="System" title="Logs" description="Trace AI prompts, model versions, outputs, and failures." action={<SortBar sort={sort} setSort={setSort} options={["Newest", "Operation"]} />} /><section className="panel table-panel"><div className="panel-header"><div><h2>AI generation history</h2><p>Prompt version and output history for this workspace.</p></div></div>{rows.length ? <div className="table-wrap"><table className="data-table"><thead><tr><th>Created</th><th>Operation</th><th>Business</th><th>Tone</th><th>Model</th><th>Version</th></tr></thead><tbody>{rows.map((row) => <tr key={row.id}><td className="mono">{new Date(row.createdAt).toLocaleString("en-IN")}</td><td><span className="badge badge-blue">{row.kind}</span></td><td>{row.businessName}</td><td>{row.tone}</td><td className="mono">{row.model || "default"}</td><td className="mono">{row.promptVersion}</td></tr>)}</tbody></table></div> : <EmptyState message={history.isLoading ? "Loading AI history…" : "No AI operations have run yet."} action="Find leads" onAction={() => toast("Use Find leads from the sidebar")} />}</section></>; }
function Settings() { const [config, setConfig] = useState(getConfig()); const [saved, setSaved] = useState(false); const update = (key: keyof Config, value: string) => setConfig((current) => ({ ...current, [key]: value })); const save = () => { window.localStorage.setItem(CONFIG_KEY, JSON.stringify(config)); setSaved(true); toast.success("Settings saved"); }; return <><PageHeader eyebrow="System" title="Settings" description="Control workspace identity, payments, Netlify demos, and AI defaults." action={saved ? <span className="saved-indicator"><Check size={14} />Saved</span> : undefined} /><div className="settings-layout"><div className="settings-nav"><button className="settings-nav-active">Workspace</button><button>Payments</button><button>Integrations</button><button>Data</button></div><div className="settings-content"><SettingSection title="Workspace" description="Used in invoices, demos, and outreach context."><div className="setting-row"><div><strong>Business name</strong><span>Shown on PDFs and demo pages.</span></div><input value={config.businessName} onChange={(e) => update("businessName", e.target.value)} placeholder="Your studio name" /></div><div className="setting-row"><div><strong>Owner name</strong><span>Shown on business documents.</span></div><input value={config.ownerName} onChange={(e) => update("ownerName", e.target.value)} placeholder="Your name" /></div><div className="setting-row"><div><strong>Default project rate</strong><span>Used when a lead has no value.</span></div><input value={config.projectRate} onChange={(e) => update("projectRate", e.target.value)} inputMode="numeric" placeholder="7500" /></div></SettingSection><SettingSection title="Payments" description="India-first invoice and payment defaults."><div className="setting-row"><div><strong>PAN</strong><span>Printed on invoice PDFs.</span></div><input value={config.pan} onChange={(e) => update("pan", e.target.value)} placeholder="ABCDE1234F" /></div><div className="setting-row"><div><strong>UPI ID</strong><span>Used for UPI links and QR codes.</span></div><input value={config.upiId} onChange={(e) => update("upiId", e.target.value)} placeholder="you@upi" /></div></SettingSection><SettingSection title="Integrations" description="Tokens stay in this browser for now. Move them server-side before a public deployment."><div className="setting-row"><div><strong>Netlify personal access token</strong><span>Required for one-click demo deploys.</span></div><input type="password" value={config.netlifyToken} onChange={(e) => update("netlifyToken", e.target.value)} placeholder="nfp_..." /></div></SettingSection><div className="settings-footer"><button className="button primary" onClick={save}>Save changes</button></div></div></div></>; }
function SettingSection({ title, description, children }: { title: string; description: string; children: ReactNode }) { return <section className="settings-section"><div className="settings-section-head"><h2>{title}</h2><p>{description}</p></div>{children}</section>; }

export default function Home() { const [location] = useLocation(); const [light, setLight] = useState(false); const page = useMemo(() => { switch (location) { case "/today": return <Today />; case "/find-leads": return <FindLeads />; case "/add-leads": return <AddLeads />; case "/pipeline": return <PipelineView />; case "/ai-tools": return <AI_tools />; case "/revenue": return <Revenue />; case "/logs": return <Logs />; case "/settings": return <Settings />; default: return <Dashboard />; } }, [location]); return <Shell light={light} onThemeToggle={() => { setLight((v) => !v); document.documentElement.classList.toggle("light"); }}>{page}</Shell>; }
export { StatusBadge, MetricCard, SettingSection };
